    let original = Order(id: 1, quantity: 7, status: .approved)
    let changed = original.copy(quantity: 9)

    #expect(changed.quantity == 9)
    #expect(changed.id == 1)
    #expect(changed.status == .approved)
    #expect(original.quantity == 7)
